// Controller public P -> R -> A -> Q pipeline over the frozen bounded R fixture.
#![forbid(unsafe_code)]
use serde_json::{Value,json};
use water_contracts::v1::{self as a,OpaqueId};
use water_scope_registry::v1::Registry;
use water_native_scan::v1 as r;
fn id(s:&str)->OpaqueId{OpaqueId::new(s).unwrap()}
fn wire(scan:&r::NativeScan)->Value{serde_json::from_str(&r::to_json(scan).unwrap()).unwrap()}
fn main(){let i:Value=serde_json::from_str(&std::fs::read_to_string(std::env::var("WATER_NATIVE_WALK_INDEX").unwrap()).unwrap()).unwrap();let mut registry=Registry::new(4).unwrap();let pending=registry.prepare(&id("scope-native"),i["root"].as_str().unwrap()).unwrap();let scope=registry.confirm(&pending).unwrap();let options=r::ScanOptions::new(8,128,32).unwrap();let scan=r::scan_registered(&mut registry,&scope,i["root"].as_str().unwrap(),&id("native-controller-scan"),&options,&r::CancelToken::new()).unwrap();let full=wire(&scan);assert_eq!(full["native_scan_version"],"water.native-scan.v1");assert_eq!(full["source_kind"],"native_scope_metadata");assert_eq!(full["status"],"completed");assert_eq!(full["visited_entries"],8);assert_eq!(full["recorded_entries"],8);assert_eq!(full["issues"],json!([]));assert_eq!(full["entries"].as_array().unwrap().len(),8);
for (entry,expected)in full["entries"].as_array().unwrap().iter().zip(i["expected_entries"].as_array().unwrap()){assert_eq!(entry["relative_path"],expected[0]);assert_eq!(entry["kind"],expected[1]);assert_eq!(entry["logical_bytes"],expected[2]);assert_eq!(entry["depth"],expected[3]);assert!(entry["allocated_bytes"].is_null());}assert_eq!(full["entries"][0]["native_identity"],full["entries"][1]["native_identity"]);assert!(!full["entries"][0]["native_identity"].is_null());assert!(full["entries"][5]["native_identity"].is_null());assert!(!full.to_string().contains("TRAP_OUTSIDE"));assert!(!full.to_string().contains(i["root"].as_str().unwrap()));assert_eq!(full["native_user_gesture_authenticated"],false);assert_eq!(full["race_protection_verified"],false);
a::validate_report(scan.report()).unwrap();let report=a::parse_report(&a::to_json(scan.report()).unwrap()).unwrap();assert_eq!(&report,scan.report());assert!(report.totals.logical_bytes.is_none()&&report.totals.allocated_bytes.is_none());let export=r::redacted_json(&scan).unwrap();assert_eq!(export,water_redacted_report::v1::to_json(&water_redacted_report::v1::redact_report(scan.report()).unwrap()).unwrap());for path in ["alpha.txt","dir/inner.txt","literal-秘密.txt","TRAP_OUTSIDE"]{assert!(!export.contains(path));}let next=registry.begin_scan(&scope).unwrap();registry.finish(&next).unwrap();assert!(matches!(r::scan_registered(&mut registry,&scope,i["trap"].as_str().unwrap(),&id("wrong-root"),&options,&r::CancelToken::new()),Err(r::NativeScanError::RootMismatch)));let next=registry.begin_scan(&scope).unwrap();registry.finish(&next).unwrap();let token=r::CancelToken::new();token.cancel();let cancelled=r::scan_registered(&mut registry,&scope,i["missing"].as_str().unwrap(),&id("cancelled-native"),&options,&token).unwrap();assert_eq!(wire(&cancelled)["status"],"cancelled");assert_eq!(wire(&cancelled)["recorded_entries"],0);registry.revoke(&scope).unwrap();assert!(r::scan_registered(&mut registry,&scope,i["root"].as_str().unwrap(),&id("revoked-native"),&options,&r::CancelToken::new()).is_err());
let cases:Value=serde_json::from_str(include_str!("../../contracts/native-scan-v1/decoder-cases.json")).unwrap();for c in cases["valid"].as_array().unwrap(){let bytes:Vec<u8>=serde_json::from_value(c["bytes"].clone()).unwrap();let actual=r::decode_directory_buffer(&bytes).unwrap();assert_eq!(actual.len(),c["records"].as_array().unwrap().len());for (a,e)in actual.iter().zip(c["records"].as_array().unwrap()){let name:Vec<u16>=serde_json::from_value(e["name"].clone()).unwrap();assert_eq!(a.name_utf16(),name);assert_eq!(a.attributes(),e["attributes"].as_u64().unwrap()as u32);}}for c in cases["invalid"].as_array().unwrap(){let bytes:Vec<u8>=if let Some(n)=c["zero_bytes"].as_u64(){vec![0;n as usize]}else{serde_json::from_value(c["bytes"].clone()).unwrap()};assert!(matches!(r::decode_directory_buffer(&bytes),Err(r::NativeScanError::MalformedDirectoryBuffer)));}for c in cases["names_valid"].as_array().unwrap(){let name:Vec<u16>=serde_json::from_value(c["name"].clone()).unwrap();assert_eq!(r::validate_child_name(&name).unwrap(),c["expected"].as_str().unwrap());}for c in cases["names_invalid"].as_array().unwrap(){let name:Vec<u16>=serde_json::from_value(c["name"].clone()).unwrap();assert!(matches!(r::validate_child_name(&name),Err(r::NativeScanError::InvalidChildName)));}
println!("{}",json!({"actual_P_R_A_Q":true,"entries":8,"root_binding_and_cleanup":true,"decoder_valid":5,"decoder_invalid":10,"name_valid":cases["names_valid"].as_array().unwrap().len(),"name_invalid":cases["names_invalid"].as_array().unwrap().len(),"ordinary_content_read":false,"native_picker_tested":false}));}
